import{_ as t,c as a,b as n,o}from"./app-CpW5lisY.js";const i={};function s(r,e){return o(),a("div",null,e[0]||(e[0]=[n('<p>We are here with another feature within <a href="https://store.webkul.com/Shopify-Multi-Vendor-Marketplace.html" target="_blank" rel="noopener noreferrer">the Multivendor Marketplace App</a> for Shopify called &quot;<strong>Admin Staff</strong>&quot;.</p><p>It enables the store owner to add members and assign different permissions to them in order to manage activities on admin panel.</p><p>Once the charges have been approved, an additional USD 10 per month will be added to your current multivendor plan.</p><h3 id="features-of-admin-staff" tabindex="-1"><a class="header-anchor" href="#features-of-admin-staff"><span>Features of Admin Staff</span></a></h3><p>Admin can add staff members from his panel.</p><p>He can permit him/her to manage admin&#39;s account on his behalf.</p><p>Additionally, the admin can also deny access to any section of his account as needed.</p><p>Admin can see all the activities of the staff in &quot;Admin Staff Activity&quot; section.</p><p>He can edit, delete or disable the staff as per his requirement.</p><p>Now admin can give access to the staff subcategory wise.</p><h3 id="activation-of-this-feature-in-admin-staff" tabindex="-1"><a class="header-anchor" href="#activation-of-this-feature-in-admin-staff"><span>Activation of this Feature in Admin Staff</span></a></h3><p>To make this feature work within the app, you need to enable it from the &quot;Feature App&quot; section of the admin panel.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/Dashboard-Admin-1.png" alt="Feature App"></p><p>Scroll down to get the feature and click on &quot;Enable&quot; button to activate this feature.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/Screenshot-22.png" alt="Feature App enable"></p><p>Once you click this enable button, you need to agree with the additional amount of USD 10 and approve the charges.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/Screenshot-23.png" alt="Agree"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/Screenshot-24.png" alt="Approve the charge Admin Staff"></p><p>In this way, you can activate this feature within your Multivendor app.</p><h3 id="how-does-this-feature-work" tabindex="-1"><a class="header-anchor" href="#how-does-this-feature-work"><span>How does this feature work</span></a></h3><p>To add staff members, the admin should initially navigate to the &#39;Seller&#39; section. Next, they need to click on the &#39;Add Staff&#39; button within the &#39;My Staff&#39; menu.</p><p>Furthermore, this process enables streamlined management of staff accounts</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/Dashboard-Admin-2.png" alt="Add staff"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/My-Staff-Admin.png" alt="Admin Staff"></p><p>In this section, the admin can easily add staffs by providing their details and subsequently manage their permissions by granting or denying access as needed.</p><p>Additionally, the admin now has the option to select subcategories to assign specific access to staffs members, as shown in the provided image, ensuring more detailed permission management.</p><p>Additionally, this feature offers more granular control over staff permissions.</p><p><strong>Note:</strong> For the existing staff member, by default, the subcategory permission of the selected category is already selected or, in other words, is automatically permitted.</p><p>When the admin wants to modify access, they must manually update the settings by ticking or unticking the appropriate checkboxes.</p><p>Additionally, this process ensures precise control over granted permissions</p><p>Furthermore, it is important to carefully verify the selections to ensure accurate access control.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/07/m2-1200x474.png" alt="Admin Staff"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/07/m3-832x1024.png" alt="Admin Staff"></p><p>Once the <strong>admin clicks the Save button</strong> after entering all staff details, the system <strong>adds the staff member</strong> successfully.</p><p>The newly added staff member <strong>receives an email notification</strong> once the admin grants permission.</p><p>The system also <strong>sends login credentials via email</strong>, allowing the staff member to <strong>access the admin’s account</strong>.</p><p>As an admin, you can <strong>customize the content of this email</strong> from the <strong>&quot;Mail Configuration&quot;</strong> section.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/Mail-Configuration-Admin.png" alt="Mail Configuration"></p><p>Once the staff gets all the details via mail, he can manage admin&#39;s account on his behalf.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/admin.webp" alt="Admin Staff"></p><p>Now you will find the change password for staff template in the mail settings</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/admin3-1200x352.webp" alt="admin"></p><p>Now admin can change the staffs password by following steps:</p><p>Admin&gt;&gt;Sellers&gt;&gt;My Staff&gt;&gt;Three dots&gt;&gt;Edit Staff&gt;&gt;Change Password&gt;&gt;Save</p><p>Now, the admin will provide a public URL to his staff from where the staff can login to the admin&#39;s account to manage permitted activities.</p><p>You can get this public URL for your staff from the &quot;Instruction for Marketplace&quot; menu of the admin panel in the &quot;Configuration&quot; section.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/11/admin-staff-1200x627.webp" alt="admin staff"></p><p>Once this URL is entered, a login page for your staff is automatically displayed.</p><p>Staff can use his credentials received via mail to get access to the admin&#39;s account.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/Login-Admin-•-Multivendor-MarketPlace.png" alt="Staff Login"></p><p>Once the staff logs into this page, they are redirected to the admin panel, where the sections of the admin account permitted by the admin can be managed by the staff member.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/Home-Admin.png" alt="Staff Account"></p><p>After accessing the &#39;My Account&#39; section, the staff member will subsequently find options to update account details.</p><p>Moreover, they can also change their account password as per their preference</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/Add-Staff-Admin-1.png" alt="Staff"></p><p>That is how, an added staff can manage the admin&#39;s account.</p><h3 id="demo-link" tabindex="-1"><a class="header-anchor" href="#demo-link"><span>Demo Link</span></a></h3><p><a href="https://multivendor-marketplace-5.myshopify.com" target="_blank" rel="noopener noreferrer">https://multivendor-marketplace-5.myshopify.com</a></p>',58)]))}const l=t(i,[["render",s]]),c=JSON.parse('{"path":"/classic/Featured-App/Marketplace%20Miscellaneous%20Add-ons/ADMIN%20STAFF.html","title":"ADMIN STAFF","lang":"en-US","frontmatter":{"title":"ADMIN STAFF","description":"ADMIN STAFF","date":"2025-07-25T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[{"level":3,"title":"Features of Admin Staff","slug":"features-of-admin-staff","link":"#features-of-admin-staff","children":[]},{"level":3,"title":"Activation of this Feature in Admin Staff","slug":"activation-of-this-feature-in-admin-staff","link":"#activation-of-this-feature-in-admin-staff","children":[]},{"level":3,"title":"How does this feature work","slug":"how-does-this-feature-work","link":"#how-does-this-feature-work","children":[]},{"level":3,"title":"Demo Link","slug":"demo-link","link":"#demo-link","children":[]}],"git":{"updatedTime":1757583088000,"contributors":[{"name":"pratik","username":"pratik","email":"pratik@webkul.com","commits":1,"url":"https://github.com/pratik"}],"changelog":[{"hash":"bbe1b03e5e919255cadeb8590203b7f1b2e7378e","time":1757583088000,"email":"pratik@webkul.com","author":"pratik","message":"add some new file"}]},"filePathRelative":"classic/Featured-App/Marketplace Miscellaneous Add-ons/ADMIN STAFF.md"}');export{l as comp,c as data};
